body += r"""    <script>
    (function(){ var T=document.getElementById('sbTown'), S=document.getElementById('sbSheet'), N=document.getElementById('sbNote'), G=document.getElementById('sbGroup'); if (!T||!S) return;
      var MON=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'], cache={}, pending=null;
      var label=function(f){ return (f.date? (MON[parseInt(f.date.slice(5,7),10)-1]||'')+' '+f.date.slice(0,4) : 'Edition '+f.ed)+' · sheet '+f.sheet; };
      var load=function(slug, place, then){ if (cache[slug]){ then(cache[slug]); return; } N.textContent='Fetching the sheet list from Wikimedia Commons…';
        var pre='Sanborn Fire Insurance Map from '+place+', Michigan. LOC sanborn';
        var u='https://commons.wikimedia.org/w/api.php?action=query&format=json&origin=*&generator=allimages&gailimit=200&gaiprefix='+encodeURIComponent(pre)+'&prop=imageinfo&iiprop=url|size|extmetadata&iiurlwidth=3840&iiextmetadatafilter=DateTimeOriginal';
        fetch(u).then(function(r){ return r.json(); }).then(function(j){ var L=[]; Object.keys((j.query&&j.query.pages)||{}).forEach(function(k){ var p=j.query.pages[k], ii=p.imageinfo&&p.imageinfo[0]; if (!ii || !/\.jpg$/i.test(p.title)) return; var m=/_(\d{3})-(\d+)\.jpg$/i.exec(p.title.replace(/ /g,'_')); if (!m) return; var d=ii.extmetadata&&ii.extmetadata.DateTimeOriginal&&ii.extmetadata.DateTimeOriginal.value||''; L.push({ed:m[1], sheet:+m[2], date:(d.match(/\d{4}-\d{2}/)||[''])[0], url:ii.thumburl||ii.url, w:ii.thumbwidth||ii.width, h:ii.thumbheight||ii.height, page:ii.descriptionurl}); });
          L.sort(function(a,b){ return a.ed===b.ed? a.sheet-b.sheet : a.ed<b.ed?-1:1; }); cache[slug]=L; N.textContent=L.length? L.length+' sheets. The Library of Congress’s scans, shown from Wikimedia Commons. Public domain.' : 'No sheets came back from Wikimedia Commons just now. Try again in a minute.'; then(L); })
        .catch(function(){ N.textContent='Wikimedia Commons did not answer. Try again in a minute.'; }); };
      var fill=function(L){ S.innerHTML=''; L.forEach(function(f,i){ var o=document.createElement('option'); o.value=i; o.textContent=label(f); S.appendChild(o); }); S.disabled=!L.length; };
      var show=function(slug, place, i, r){ var f=cache[slug][i]; if (!f || !window.psMap) return; var key='sb-'+slug+'-'+f.ed+'-'+f.sheet, town=place.split(',')[0];
        if (!window.psMap.maps[key]){ window.psMap.maps[key]={src:{type:'image', url:f.url}, name:'Sanborn map of '+town+', '+label(f), size:f.w.toLocaleString('en-US')+' × '+f.h.toLocaleString('en-US'), from:'Wikimedia Commons (the Library of Congress’s scan)', local:false}; if (G){ var o=document.createElement('option'); o.value=key; o.textContent=town+' · '+label(f); G.appendChild(o); } }
        window.psMap.goTo({m:key, n:town, r:r, msg:'Sanborn map of '+town+', '+label(f)+'. Zoom in to read the buildings; “Whole map” shows the whole sheet.'}); };
      T.addEventListener('change', function(){ if (!T.value) return; var p=T.value.split('|'); load(p[0], p[1], function(L){ fill(L); if (L.length) show(p[0], p[1], 0); }); });
      S.addEventListener('change', function(){ var p=T.value.split('|'); show(p[0], p[1], +S.value); });
      var fromHash=function(){ var m=/^#sanborn-([a-z-]+)(?:\/(\d{3})-(\d+))?(?:\/([\d,]+))?$/.exec(location.hash); if (!m) return; var opt=[].slice.call(T.options).filter(function(o){ return o.value.split('|')[0]===m[1]; })[0]; if (!opt) return; T.value=opt.value; var p=opt.value.split('|');
        load(p[0], p[1], function(L){ fill(L); var i=0; if (m[2]) L.forEach(function(f,k){ if (f.ed===m[2] && f.sheet===+m[3]) i=k; }); S.value=i; show(p[0], p[1], i, m[4]? m[4].split(',').map(Number) : null); }); };
      if (location.hash==='#sanborn') document.getElementById('sanborn').scrollIntoView(); fromHash(); addEventListener('hashchange', fromHash);
    })();
    </script>
"""
